// Differential test: /output's sort_linked (verbatim) vs a direct transcription
// of the canonical earcut.hpp sortLinked.

pub const NULL: usize = usize::MAX;

#[derive(Clone, Copy, Debug)]
struct Node {
    z: i32,
    id: usize, // stability tag
    prev_z: usize,
    next_z: usize,
}

struct Arena {
    n: Vec<Node>,
}
impl std::ops::Index<usize> for Arena {
    type Output = Node;
    fn index(&self, h: usize) -> &Node {
        &self.n[h]
    }
}
impl std::ops::IndexMut<usize> for Arena {
    fn index_mut(&mut self, h: usize) -> &mut Node {
        &mut self.n[h]
    }
}

struct E {
    nodes: Arena,
}

impl E {
    // ============ VERBATIM COPY from /output/src/mapbox/earcut.rs ============
    fn sort_linked(&mut self, list_in: usize) -> usize {
        debug_assert!(list_in != NULL);
        let mut list = list_in;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0;
                let mut i = 0;
                while i < in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                    i += 1;
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }
    // ============ END VERBATIM COPY ============

    // Direct transcription of canonical earcut.hpp sortLinked (C for-loop kept literal).
    fn sort_linked_canon(&mut self, list_in: usize) -> usize {
        let mut list = list_in;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0i32;
                // for (i = 0; i < inSize; i++) { pSize++; q = q->nextZ; if (!q) break; }
                let mut i = 0i32;
                loop {
                    if !(i < in_size) {
                        break;
                    }
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                    i += 1; // the C for-loop increment
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }
                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }
                    self.nodes[e].prev_z = tail;
                    tail = e;
                }
                p = q;
            }

            self.nodes[tail].next_z = NULL;
            if num_merges <= 1 {
                return list;
            }
            in_size *= 2;
        }
    }
}

fn build(zs: &[i32]) -> E {
    let n: Vec<Node> = zs
        .iter()
        .enumerate()
        .map(|(k, &z)| Node {
            z,
            id: k,
            prev_z: if k == 0 { NULL } else { k - 1 },
            next_z: if k + 1 == zs.len() { NULL } else { k + 1 },
        })
        .collect();
    E { nodes: Arena { n } }
}

// walk forward, also verify prev_z consistency
fn dump(e: &E, head: usize) -> (Vec<(i32, usize)>, bool) {
    let mut out = Vec::new();
    let mut prev = NULL;
    let mut p = head;
    let mut ok = true;
    let mut guard = 0;
    while p != NULL {
        if e.nodes[p].prev_z != prev {
            ok = false;
        }
        out.push((e.nodes[p].z, e.nodes[p].id));
        prev = p;
        p = e.nodes[p].next_z;
        guard += 1;
        if guard > 100000 {
            ok = false;
            break;
        }
    }
    (out, ok)
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
}

fn main() {
    let mut rng = Rng(0x1234_5678_9abc_def1);
    let mut cases = 0usize;
    let mut diffs = 0usize;

    // exhaustive-ish small deterministic cases
    let mut fixed: Vec<Vec<i32>> = Vec::new();
    for len in 1..=9usize {
        fixed.push((0..len as i32).collect());
        fixed.push((0..len as i32).rev().collect());
        fixed.push(vec![7; len]);
        let mut v: Vec<i32> = (0..len as i32).collect();
        v.reverse();
        v.iter_mut().for_each(|x| *x /= 2);
        fixed.push(v);
    }

    for zs in fixed.iter() {
        let mut a = build(zs);
        let mut b = build(zs);
        let ha = a.sort_linked(0);
        let hb = b.sort_linked_canon(0);
        let (da, oka) = dump(&a, ha);
        let (db, okb) = dump(&b, hb);
        cases += 1;
        if da != db || !oka || !okb {
            diffs += 1;
            println!("FIXED DIFF len={} zs={:?}\n port  ={:?} ok={}\n canon ={:?} ok={}", zs.len(), zs, da, oka, db, okb);
        }
        // also compare against std stable sort by z
        let mut expect: Vec<(i32, usize)> = zs.iter().copied().enumerate().map(|(k, z)| (z, k)).collect();
        expect.sort_by_key(|&(z, _)| z);
        if da != expect {
            println!("NOT STABLE-SORTED (port) len={} zs={:?} got={:?} want={:?}", zs.len(), zs, da, expect);
            diffs += 1;
        }
    }

    for _ in 0..200000 {
        let len = (rng.below(24) + 1) as usize;
        let range = 1 + rng.below(6); // heavy duplicates when small
        let zs: Vec<i32> = (0..len).map(|_| rng.below(range) as i32).collect();
        let mut a = build(&zs);
        let mut b = build(&zs);
        let ha = a.sort_linked(0);
        let hb = b.sort_linked_canon(0);
        let (da, oka) = dump(&a, ha);
        let (db, okb) = dump(&b, hb);
        cases += 1;
        if da != db || !oka || !okb {
            diffs += 1;
            if diffs < 10 {
                println!("RAND DIFF zs={:?}\n port ={:?} ok={}\n canon={:?} ok={}", zs, da, oka, db, okb);
            }
        }
        let mut expect: Vec<(i32, usize)> = zs.iter().copied().enumerate().map(|(k, z)| (z, k)).collect();
        expect.sort_by_key(|&(z, _)| z);
        if da != expect {
            diffs += 1;
            if diffs < 20 {
                println!("NOT STABLE zs={:?} got={:?} want={:?}", zs, da, expect);
            }
        }
    }

    // bigger lists, wide z range (incl. negatives which real z never has, but harmless)
    for _ in 0..2000 {
        let len = (rng.below(500) + 1) as usize;
        let zs: Vec<i32> = (0..len).map(|_| (rng.below(1 << 30)) as i32).collect();
        let mut a = build(&zs);
        let mut b = build(&zs);
        let ha = a.sort_linked(0);
        let hb = b.sort_linked_canon(0);
        let (da, oka) = dump(&a, ha);
        let (db, okb) = dump(&b, hb);
        cases += 1;
        if da != db || !oka || !okb {
            diffs += 1;
            if diffs < 25 {
                println!("BIG DIFF len={}", len);
            }
        }
        let mut expect: Vec<(i32, usize)> = zs.iter().copied().enumerate().map(|(k, z)| (z, k)).collect();
        expect.sort_by_key(|&(z, _)| z);
        if da != expect {
            diffs += 1;
            println!("BIG NOT STABLE len={}", len);
        }
    }

    println!("cases={} diffs={}", cases, diffs);
}

#include <cstdint>
#include <cstdio>
#include <cmath>
#include <cstring>

// canonical earcut.hpp zOrder
static double minX, minY, inv_size;
int32_t zOrder(const double x_, const double y_) {
    // coords are transformed into non-negative 15-bit integer range
    int32_t x = static_cast<int32_t>((x_ - minX) * inv_size);
    int32_t y = static_cast<int32_t>((y_ - minY) * inv_size);

    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x33333333;
    x = (x | (x << 1)) & 0x55555555;

    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x33333333;
    y = (y | (y << 1)) & 0x55555555;

    return x | (y << 1);
}

static uint64_t st = 0x9E3779B97F4A7C15ull;
uint64_t rnd() { st ^= st << 13; st ^= st >> 7; st ^= st << 17; return st; }
double rd() { return (double)(rnd() >> 11) / (double)(1ull << 53); }

int main() {
    for (int trial = 0; trial < 20000; trial++) {
        minX = (rd() - 0.5) * 2000.0;
        minY = (rd() - 0.5) * 2000.0;
        double dx = rd() * 1000.0;
        double dy = rd() * 1000.0;
        double size = dx > dy ? dx : dy;
        inv_size = size != 0.0 ? 32767.0 / size : 0.0;
        for (int k = 0; k < 20; k++) {
            double x = minX + rd() * dx;
            double y = minY + rd() * dy;
            printf("%.17g %.17g %.17g %.17g %.17g %d\n", x, y, minX, minY, inv_size, zOrder(x, y));
        }
        // exact corners
        printf("%.17g %.17g %.17g %.17g %.17g %d\n", minX, minY, minX, minY, inv_size, zOrder(minX, minY));
        printf("%.17g %.17g %.17g %.17g %.17g %d\n", minX+dx, minY+dy, minX, minY, inv_size, zOrder(minX+dx, minY+dy));
        printf("%.17g %.17g %.17g %.17g %.17g %d\n", minX+size, minY+size, minX, minY, inv_size, zOrder(minX+size, minY+size));
    }
    // degenerate: inv_size == 0
    minX = 1.0; minY = 2.0; inv_size = 0.0;
    printf("%.17g %.17g %.17g %.17g %.17g %d\n", 1.0, 2.0, minX, minY, inv_size, zOrder(1.0, 2.0));
    // integer-boundary / negative-fraction truncation probes
    minX = 0.0; minY = 0.0; inv_size = 1.0;
    for (int k = 0; k <= 32770; k++) {
        double v = (double)k;
        printf("%.17g %.17g %.17g %.17g %.17g %d\n", v, v, minX, minY, inv_size, zOrder(v, v));
    }
    // negative products (point below minX -- shouldn't happen but probe C truncation toward zero)
    for (int k = 1; k <= 50; k++) {
        double v = -(double)k * 0.5;
        printf("%.17g %.17g %.17g %.17g %.17g %d\n", v, v, minX, minY, inv_size, zOrder(v, v));
    }
    return 0;
}

