//! A pure-`std` Rust port of the `mapbox::earcut` polygon triangulation
//! library (`earcut.hpp`).
//!
//! The public surface mirrors the C++ one:
//!
//! ```text
//! std::vector<N> mapbox::earcut<N>(const Polygon& poly)
//! ```
//!
//! becomes
//!
//! ```text
//! fn mapbox::earcut::<N, _, _>(poly: &[Ring]) -> Vec<N>
//! ```
//!
//! where a `Polygon` is a sequence of rings, the first ring being the outer
//! boundary and any remaining rings being holes.

// This library is a general purpose port; the `test10` binary only reaches a
// slice of its surface, so unused-item lints are not informative here.
#![allow(dead_code)]

pub mod earcut;
pub mod geom;
pub mod index;
pub mod node;
pub mod point;

// Convenience re-exports mirroring the `mapbox::` namespace.
#[allow(unused_imports)]
pub use self::earcut::{earcut, Earcut};
#[allow(unused_imports)]
pub use self::index::IndexType;
#[allow(unused_imports)]
pub use self::point::Point2D;

input.new_string:
    self.sort_linked(p);
    self.validate_z(start);
}

/// AUDIT INSTRUMENTATION (not present in /output): after index_curve, the
/// z-list must be a stable sort (by z) of the ring order starting at
/// `start`, doubly linked and NULL-terminated at both ends.
fn validate_z(&self, start: usize) {
    // ring order starting at start
    let mut ring: Vec<usize> = Vec::new();
    let mut p = start;
    loop {
        ring.push(p);
        p = self.nodes[p].next;
        if p == start {
            break;
        }
    }
    // expected = stable sort of ring by z
    let mut expect: Vec<usize> = ring.clone();
    expect.sort_by_key(|&h| self.nodes[h].z);

    // find head of z list: walk prev_z from start
    let mut head = start;
    let mut guard = 0;
    while self.nodes[head].prev_z != NULL {
        head = self.nodes[head].prev_z;
        guard += 1;
        assert!(guard <= ring.len() + 2, "prev_z cycle");
    }
    let mut got: Vec<usize> = Vec::new();
    let mut q = head;
    let mut prev = NULL;
    while q != NULL {
        assert_eq!(self.nodes[q].prev_z, prev, "prev_z inconsistent");
        got.push(q);
        prev = q;
        q = self.nodes[q].next_z;
        assert!(got.len() <= ring.len() + 2, "next_z cycle/overlong");
    }
    assert_eq!(got.len(), ring.len(), "z list length != ring length");
    assert_eq!(got, expect, "z list is not the stable sort of ring order");
    // z values must be non-decreasing
    for w in got.windows(2) {
        assert!(self.nodes[w[0]].z <= self.nodes[w[1]].z, "z not sorted");
    }
    // every z must equal z_order of its coords (memoised-on-0 quirk aside)
    for &h in got.iter() {
        let (x, y) = (self.nodes[h].x, self.nodes[h].y);
        assert_eq!(self.nodes[h].z, self.z_order(x, y), "z != z_order(x,y)");
    }
    unsafe {
        VALIDATED += 1;
        NODES_SEEN += ring.len();
    }
}

